package com.bank.repos.service;

import com.bank.repos.model.Account;
import com.bank.repos.repository.*;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.data.domain.*;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import java.math.BigDecimal;
import java.util.List;

@Slf4j
@Service
@RequiredArgsConstructor
public class AccountBatchService {
    private final SimpleAccountRepository simpleRepo;   // CrudRepository
    private final BatchAccountRepository batchRepo;     // JpaRepository

    // CrudRepository: single lookup
    @Transactional(readOnly = true)
    public Account find(String id) {
        return simpleRepo.findById(id).orElseThrow();
    }

    // JpaRepository: bulk import with saveAll + single flush (efficient batching)
    @Transactional
    public void importAccounts(List<Account> accounts) {
        batchRepo.saveAll(accounts);  // batched inserts (batch_size=500)
        batchRepo.flush();            // one flush at the end, not per row
        log.info("Imported {} accounts in batches", accounts.size());
    }

    // JpaRepository: bulk delete in a single statement (no per-row callbacks)
    @Transactional
    public void purgeAll() {
        batchRepo.deleteAllInBatch();  // single DELETE, bypasses @PreRemove
        log.warning("Purged all accounts via deleteAllInBatch");
    }
}
